()=>{const decide=FURYBOT.decide;FURYBOT.decide=function(S){decide.call(this,S);if(run.stage===5&&!bossActive&&s5run&&!s5run.done&&!s5run.failed){const g=s5run.gates.find(g=>!g.passed&&!g.missed);if(g){this.keyEvents=[];this.nextEvasion=this.age()+.3;this.commands=[Math.abs(player.x-g.x)>7?Math.sign(g.x-player.x):0,Math.abs(player.y-(VH-74))>7?Math.sign(VH-74-player.y):0];}}};FURYBOT.events.push({t:FURYBOT.age(),type:'controller-policy',note:'Attempt earned optional Stage9 by steering through visible Stage5 portal mouths with native movement; no gate/unlock edits.'});return{route:'Attempt eight real gates to include optional Stage9'};}
